import pandas as pd
from pandas import json_normalize
from ssi_fc_data import fc_md_client,model
class StockData:
	def __init__(A,client,config):A.client=client;A.config=config
	def listing(A,market=bytes([72,79,83,69]).decode(),page=1,size=1000):'\n        Lấy danh sách chứng khoán.\n\n        Args:\n            market (str): Tên sàn giao dịch: HOSE, HNX, UPCOM. Mặc định là HOSE.\n            page (int): Số trang. Mặc định là 1.\n            size (int): Kích thước trang. Mặc định là 1000.\n\n        Returns:\n            pd.DataFrame: DataFrame chứa danh sách chứng khoán.\n        ';C=model.securities(market,page,size);B=A.client.securities(A.config,C);print(bytes([84,225,187,149,110,103,32,115,225,187,145,32,98,225,186,163,110,32,103,104,105,58,32]).decode()+str(B[bytes([116,111,116,97,108,82,101,99,111,114,100]).decode()]));return pd.DataFrame(B[bytes([100,97,116,97]).decode()])
	def details(B,symbol=bytes([65,67,66]).decode(),market=bytes([72,79,83,69]).decode(),page=1,size=100):'\n        Lấy chi tiết của mã chứng khoán.\n\n        Args:\n            symbol (str): Mã chứng khoán. Mặc định là ACB.\n            market (str): Tên sàn giao dịch. Mặc định là HOSE.\n            page (int): Số trang. Mặc định là 1.\n            size (int): Kích thước trang. Mặc định là 100.\n\n        Returns:\n            pd.DataFrame: DataFrame chứa chi tiết chứng khoán.\n        ';D=model.securities_details(market,symbol,page,size);C=B.client.securities_details(B.config,D)[bytes([100,97,116,97]).decode()];A=json_normalize(C[0][bytes([82,101,112,101,97,116,101,100,73,110,102,111]).decode()]);A[bytes([82,101,112,111,114,116,68,97,116,101]).decode()]=C[0][bytes([82,101,112,111,114,116,68,97,116,101]).decode()];A=A.dropna(axis=1,how=bytes([97,108,108]).decode());return A
	def daily_ohlc(B,symbol=bytes([83,83,73]).decode(),start=bytes([48,49,47,48,55,47,50,48,50,51]).decode(),end=bytes([51,49,47,48,55,47,50,48,50,51]).decode(),ascending=True,page=1,size=1000):'\n        Lấy dữ liệu OHLC hàng ngày.\n\n        Args:\n            symbol (str): Mã chứng khoán. Mặc định là SSI.\n            start (str): Ngày bắt đầu (dd/MM/yyyy). Mặc định là 01/07/2023.\n            end (str): Ngày kết thúc (dd/MM/yyyy). Mặc định là 31/07/2023.\n            ascending (bool): Sắp xếp tăng dần hoặc giảm dần. Mặc định là True.\n            page (int): Số trang. Mặc định là 1.\n            size (int): Kích thước trang. Mặc định là 1000.\n\n        Returns:\n            pd.DataFrame: DataFrame chứa dữ liệu OHLC hàng ngày.\n        ';C=model.daily_ohlc(symbol,start,end,page,size,ascending);D=B.client.daily_ohlc(B.config,C)[bytes([100,97,116,97]).decode()];A=json_normalize(D);A=A.drop(columns=[bytes([84,105,109,101]).decode()]);return A
	def intraday_ohlc(A,symbol=bytes([83,83,73]).decode(),start=bytes([50,53,47,48,55,47,50,48,50,51]).decode(),end=bytes([51,49,47,48,55,47,50,48,50,51]).decode(),page=1,size=1000,ascending=True,resolution=1):'\n        Lấy dữ liệu OHLC trong ngày.\n\n        Args:\n            symbol (str): Mã chứng khoán. Mặc định là SSI.\n            start (str): Ngày bắt đầu (dd/MM/yyyy). Mặc định là 25/07/2023.\n            end (str): Ngày kết thúc (dd/MM/yyyy). Mặc định là 31/07/2023.\n            page (int): Số trang. Mặc định là 1.\n            size (int): Kích thước trang. Mặc định là 1000.\n            ascending (bool): Sắp xếp tăng dần hoặc giảm dần. Mặc định là True.\n            resolution (int): Nhóm theo phút. Mặc định là 1.\n\n        Returns:\n            pd.DataFrame: DataFrame chứa dữ liệu OHLC trong ngày.\n        ';B=model.intraday_ohlc(symbol,start,end,page,size,ascending,resolution);C=A.client.intraday_ohlc(A.config,B);return json_normalize(C[bytes([100,97,116,97]).decode()])
	def daily_price(A,symbol=bytes([83,83,73]).decode(),start=bytes([50,53,47,48,55,47,50,48,50,51]).decode(),end=bytes([51,49,47,48,55,47,50,48,50,51]).decode(),page=1,size=1000,market=''):'\n        Lấy giá cổ phiếu hàng ngày.\n\n        Args:\n            symbol (str): Mã chứng khoán. Mặc định là SSI.\n            start (str): Ngày bắt đầu (dd/MM/yyyy). Mặc định là 25/07/2023.\n            end (str): Ngày kết thúc (dd/MM/yyyy). Mặc định là 31/07/2023.\n            page (int): Số trang. Mặc định là 1.\n            size (int): Kích thước trang. Mặc định là 1000.\n            market (str): Thị trường cho mã chứng khoán. Mặc định là chuỗi rỗng.\n\n        Returns:\n            pd.DataFrame: DataFrame chứa giá cổ phiếu hàng ngày.\n        ';B=model.daily_stock_price(symbol,start,end,page,size,market);C=A.client.daily_stock_price(A.config,B)[bytes([100,97,116,97]).decode()];return json_normalize(C)
class IndexData:
	def __init__(A,client,config):A.client=client;A.config=config
	def listing(A,exchange='',page=1,size=100):'\n        Lấy danh sách mã và tên các chỉ số.\n\n        Args:\n            exchange (str, optional): Tên sàn giao dịch. Nếu không có giá trị sẽ trả về tất cả các sàn.\n\n        Returns:\n            pd.DataFrame: DataFrame chứa danh sách chỉ số.\n        ';B=model.index_list(exchange,page,size);C=A.client.index_list(A.config,B)[bytes([100,97,116,97]).decode()];return json_normalize(C)
	def component(C,index=bytes([86,78,51,48]).decode(),page=1,size=100):'\n        Lấy danh sách mã chứng khoán trong một chỉ số.\n\n        Args:\n            index (str): Mã chỉ số. Mặc định là VN30.\n            page (int): Số trang. Mặc định là 1.\n            size (int): Kích thước trang. Mặc định là 1000.\n\n        Returns:\n            pd.DataFrame: DataFrame chứa danh sách mã chứng khoán.\n        ';D=model.index_components(index,page,size);A=C.client.index_components(C.config,D)[bytes([100,97,116,97]).decode()][0];E=A[bytes([73,110,100,101,120,67,111,100,101]).decode()];F=A[bytes([69,120,99,104,97,110,103,101]).decode()];G=A[bytes([84,111,116,97,108,83,121,109,98,111,108,78,111]).decode()];print(f"Chỉ số: {E} - {F}. Tổng số {G} mã chứng khoán");B=json_normalize(A[bytes([73,110,100,101,120,67,111,109,112,111,110,101,110,116]).decode()]);B=B.drop(columns=[bytes([73,115,105,110]).decode()]);return B
	def daily_ohlc(B,index=bytes([86,78,51,48]).decode(),start=bytes([50,53,47,48,55,47,50,48,50,51]).decode(),end=bytes([51,49,47,48,55,47,50,48,50,51]).decode(),page=1,size=1000,orderBy=bytes([84,114,97,100,105,110,103,100,97,116,101]).decode(),order=bytes([100,101,115,99]).decode(),request_id=''):'\n        Trả về dữ liệu chỉ số hàng ngày.\n\n        Args:\n            index (str): Tên chỉ số. Mặc định là VN30.\n            start (str): Ngày bắt đầu (dd/MM/yyyy). Mặc định là 25/07/2023.\n            end (str): Ngày kết thúc (dd/MM/yyyy). Mặc định là 31/07/2023.\n            page (int): Số trang. Mặc định là 1.\n            size (int): Kích thước trang. Mặc định là 1000.\n            orderBy (str): Cột sắp xếp. Mặc định là Tradingdate.\n            order (str): Kiểu sắp xếp. Mặc định là giảm dần (desc).\n            request_id (str): ID yêu cầu. Mặc định là chuỗi rỗng.\n\n        Returns:\n            pd.DataFrame: DataFrame chứa dữ liệu chỉ số hàng ngày.\n        ';C=model.daily_index(request_id,index,start,end,page,size,orderBy,order);D=B.client.daily_index(B.config,C)[bytes([100,97,116,97]).decode()];A=json_normalize(D);A=A.dropna(axis=1,how=bytes([97,108,108]).decode());return A
class Config:
	def __init__(A,consumer_id,consumer_secret,access_token=None):"\n        Khởi tạo đối tượng cấu hình chứa thông tin cần thiết để kết nối tới API SSI Fast Connect.\n\n        Tham số:\n            - auth_type (str): Loại xác thực (ví dụ: 'Bearer').\n            - consumerID (str): ID người dùng.\n            - consumerSecret (str): Mật khẩu người dùng.\n            - access_token (str): Token tạo ra từ thông tin đăng nhập, sinh ra bằng cách gọi hàm get_token.\n\n        Thuộc tính:\n            - auth_type (str): Loại xác thực.\n            - consumerID (str): ID người dùng.\n            - consumerSecret (str): Mật khẩu người dùng.\n            - access_jwt (str): Mã thông báo JWT truy cập.\n            - url (str): URL của API dữ liệu thị trường.\n            - stream_url (str): URL của API dữ liệu dòng.\n        ";A.consumerID=consumer_id;A.consumerSecret=consumer_secret;A.auth_type=bytes([66,101,97,114,101,114]).decode();A.url=bytes([104,116,116,112,115,58,47,47,102,99,45,100,97,116,97,46,115,115,105,46,99,111,109,46,118,110,47]).decode();A.stream_url=bytes([104,116,116,112,115,58,47,47,102,99,45,100,97,116,97,46,115,115,105,46,99,111,109,46,118,110,47]).decode();A.access_jwt=access_token
def get_token(config):A=config;B=fc_md_client.MarketDataClient(A);C=B.access_token(model.accessToken(A.consumerID,A.consumerSecret));return C
class FCData:
	def __init__(A,config):'\n        Khởi tạo đối tượng để truy xuất dữ liệu từ SSI Fast Connect Data API.\n\n        Tham số:\n            - config (object): Đối tượng cấu hình chứa các thông tin cần thiết để kết nối tới API.\n\n        Thuộc tính:\n            - config (object): Đối tượng cấu hình được truyền vào.\n            - client (MarketDataClient): Đối tượng khách hàng để tương tác với API dữ liệu thị trường.\n            - stock (StockData): Đối tượng để truy xuất dữ liệu chứng khoán.\n            - index (IndexData): Đối tượng để truy xuất dữ liệu chỉ số.\n        ';B=config;A.config=B;A.client=fc_md_client.MarketDataClient(B);A.stock=StockData(A.client,B);A.index=IndexData(A.client,B)